{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

arguments.content:
{
  "watches": [
    {
      "name": "core-visibility",
      "targets": [
        "features/todomvc.feature:No todos hides the main section and footer"
      ]
    },
    {
      "name": "add-todo",
      "targets": [
        "features/todomvc.feature:Adding a new todo by pressing Enter",
        "features/todomvc.feature:Empty or whitespace input is not added",
        "features/todomvc.feature:The new-todo input is focused on load"
      ]
    },
    {
      "name": "toggle-all",
      "targets": [
        "features/todomvc.feature:Mark all todos as complete",
        "features/todomvc.feature:Unmark all todos via mark-all checkbox",
        "features/todomvc.feature:Mark-all reflects individual todo states"
      ]
    },
    {
      "name": "toggle-single",
      "targets": [
        "features/todomvc.feature:Toggle a single todo complete",
        "features/todomvc.feature:Toggle a completed todo back to active"
      ]
    },
    {
      "name": "editing",
      "targets": [
        "features/todomvc.feature:Double-click enters editing mode",
        "features/todomvc.feature:Editing saves on Enter",
        "features/todomvc.feature:Editing saves on blur",
        "features/todomvc.feature:Editing discards on Escape",
        "features/todomvc.feature:Editing with empty input destroys the todo",
        "features/todomvc.feature:Editing with whitespace-only input destroys the todo",
        "features/todomvc.feature:Editing trims the input value"
      ]
    },
    {
      "name": "destroy",
      "targets": [
        "features/todomvc.feature:Remove a todo by clicking its destroy button"
      ]
    },
    {
      "name": "counter",
      "targets": [
        "features/todomvc.feature:Counter shows correct count for active todos",
        "features/todomvc.feature:Counter pluralizes correctly for one item",
        "features/todomvc.feature:Counter pluralizes correctly for zero items"
      ]
    },
    {
      "name": "clear-completed",
      "targets": [
        "features/todomvc.feature:Clear completed button removes completed todos",
        "features/todomvc.feature:Clear completed button is hidden when no todos are completed",
        "features/todomvc.feature:Clear completed button is visible when todos are completed"
      ]
    },
    {
      "name": "routing",
      "targets": [
        "features/todomvc.feature:Filter shows all todos",
        "features/todomvc.feature:Filter shows only active todos",
        "features/todomvc.feature:Filter shows only completed todos",
        "features/todomvc.feature:Active filter link is selected when viewing active todos",
        "features/todomvc.feature:Completing a todo while on Active filter hides it immediately",
        "features/todomvc.feature:Completing a todo while on Completed filter shows it immediately"
      ]
    },
    {
      "name": "persistence",
      "targets": [
        "features/todomvc.feature:Todos persist to localStorage",
        "features/todomvc.feature:Active filter persists across reload"
      ]
    }
  ]
}

